# ---------------------------------------------------------------- 북쪽 승강기 홀
prop w_elev_kt 5 1
text 5 2 "일반 승강기 1. 놋쇠 문이 닫혀 있다. 층 표시 바늘이 '1'에 멈췄다." w=2
prop w_elev_kt 8 1
text 8 2 "일반 승강기 2. 문틈에 개미산 자국 — 금빛이 검게 탔다." w=2
prop w_elev_kt 11 1
text 11 2 "일반 승강기 3. 문 앞에 관람객 안내 '정원 15명 — 초과 시 운행하지 않습니다'." w=2
prop w_elev_kt 14 1 state=open
text 14 2 "일반 승강기 4. 문이 반쯤 열려 있다. 칸이 없다." w=2 scene=KT_SHAFT
prop w_cargo_kt 18 1 cond="KT_POWER != 2"
prop w_cargo_kt 18 1 state=live cond="KT_POWER == 2"
text 18 2 "화물 승강기." w=3 scene=KT_CARGO
prop w_intercom_kt 22 1 cond="KT_RING == 0"
prop w_intercom_kt 22 1 state=lit cond="KT_RING >= 1"
text 22 2 "놋쇠 인터폰. '60층 전망대 직통'." scene=KT_PHONE
prop w_gov_notice 26 1
text 26 2 "안내판 '금빛 빌딩 — 60층 전망대 · 지하 수족관 · 어린이 과학관(12층)'. 12층 글자 위에 개미 발자국 같은 흙 점."
# ---------------------------------------------------------------- 동북 비상계단(개미 흙벽 — 4층부터가 아니라 바로 계단참까지 흘러내렸다)
prop ant_soil_kt 34 3 cond="KT_QUEEN == 0 and KT_DIG == 0"
prop ant_soil_kt 34 3 state=quiet cond="KT_QUEEN == 1 and KT_DIG == 0"
prop ant_soil_kt 34 3 state=dug cond="KT_DIG >= 1"
text 34 4 "비상계단 입구를 흙이 막았다. 흙벽 너머에서 사각사각 긁는 소리. 시큼한 개미산 냄새." w=2 scene=KT_DIG cond="KT_QUEEN == 0 and KT_DIG == 0"
text 34 4 "흙벽의 구멍이 흙으로 메워졌다. 긁는 소리가 그쳤다." w=2 scene=KT_DIG cond="KT_QUEEN == 1 and KT_DIG == 0"
text 34 4 "사람이 지나갈 만큼 뚫린 흙굴. 안쪽으로 비상계단." w=2 scene=KT_DIG cond="KT_DIG >= 1"
mark from_KT-03 34 5 S
mark cargo 19 3 S
prop scent_kt 30 6 cond="KT_QUEEN == 0"
prop scent_kt 26 7 cond="KT_QUEEN == 0"
prop scent_kt 30 8 cond="KT_POWER == 2 and KT_QUEEN == 0"
prop scent_kt 24 4 cond="KT_POWER == 2 and KT_QUEEN == 0"
text 28 6 "바닥에 희미하게 반짝이는 줄. 흙벽에서 나와 로비를 한 바퀴 돌고 들어간다 — 개미가 다니는 냄새 길." w=3 cond="KT_QUEEN == 0"
# ---------------------------------------------------------------- 가운데 안내 데스크
prop info_desk_kt 17 9
text 17 10 "안내 데스크. 방송 원고가 마이크 밑에 깔렸다." w=4 scene=KT_DESK
# ---------------------------------------------------------------- 서쪽 기념품 가게
prop souvenir_kt 3 6 state=empty
text 3 7 "기념품 진열장. 금박 모형 탑이 하나만 넘어져 있다. 금 초콜릿 상자는 껍데기뿐." w=2
prop souvenir_kt 3 10
text 3 11 "안쪽 진열장은 그대로다. 금박 모형 탑 셋 · 엽서 · 금 초콜릿 상자." w=2
box 3 10 stall w=2 name="기념품 진열장"
prop safe_kt 7 13
box 7 13 safe lock=50 name="기념품 가게 금고"
prop wait_chairs 3 16
# ---------------------------------------------------------------- 동쪽 관람객 줄(그날 밤 줄이 끊긴 자리)
prop queue_kt 26 13
prop queue_kt 26 16
prop stroller_kt 30 15
text 30 15 "유모차. 빛바랜 남색 덮개 · 작은 담요. 손잡이에 관람권 두 장 — '60층 전망대 · 어른 1 어린이 1 · 21:40'. 바구니에 아이 신발 한 짝 — 짝이 없다."
box 30 15 bag name="유모차 바구니"
# ---------------------------------------------------------------- 남쪽 회전문(꾀기 — 돌리면 삐걱)
prop revolving_kt 14 19 cond="KT_REVOLVE < 2"
prop revolving_kt 14 19 state=broken cond="KT_REVOLVE == 2"
text 15 20 "금빛 회전문. 날개 사이로 강바람이 샌다." w=3 scene=KT_REVOLVE
text 19 21 "회전문 옆 여닫이문. 유리에 금 간 '금빛 빌딩' 글자." w=2
prop pillar 9 9
prop pillar 30 9
prop pillar 9 17
prop pillar 34 17
prop plant_pot 36 20
prop plant_pot 2 20
prop wait_chairs 23 18
prop wait_chairs 28 18
text 23 18 "관람객 대기 의자. 의자 밑에 반쯤 먹은 금 초콜릿 은박지 — 이빨 자국이 작다." w=2
prop rubble 7 19
prop rubble 33 13
text 33 13 "천장에서 떨어진 금빛 장식 패널. 2층 갤러리 난간이 위에서 비스듬히 내려다본다."
